 table asaya-data-room-487110.maplemonk.swiggy_po_fill_date as with po_uc_grn as ((with po_grn as ((SELECT a.po_release_Date_1, a.po_number, b.grn_po_number, a.po_vendor_name, a.po_warehouse_location, a.po_status, a.po_qty, a.po_amount, b.grn_date, b.grn_qty, b.grn_amount FROM ( SELECT DATE(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', PoCreatedAt)) AS po_release_Date_1, PoNumber AS po_number, VendorName AS po_vendor_name, FacilityName AS po_warehouse_location, Status AS po_status, SUM(IFNULL(SAFE_CAST(OrderedQty AS FLOAT64), 0)) AS po_qty, SUM(IFNULL(SAFE_CAST(PoAmount AS FLOAT64), 0)) AS po_amount FROM `asaya-data-room-487110.Maplemonk.asaya_swiggy_purchase_orders` GROUP BY 1,2,3,4,5 ) AS a LEFT JOIN ( SELECT DATE(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', CreatedAtDate)) AS grn_date, PurchaseOrderNumber AS grn_po_number, SUM(IFNULL(SAFE_CAST(ReceivedQty AS FLOAT64), 0)) AS grn_qty, SUM(IFNULL(SAFE_CAST(TotalAmount AS FLOAT64), 0)) AS grn_amount FROM `asaya-data-room-487110.Maplemonk.asaya_swiggy_goods_received` WHERE COALESCE(SAFE_CAST(DNValue AS FLOAT64), 0) = 0 GROUP BY 1,2 ) AS b ON a.po_number = b.grn_po_number)), uc as (SELECT DATE(Order_Date) AS uc_order_date, DATE(invoiceDate) AS uc_invoice_date, DATE(Dispatch_Date) AS uc_dispatch_date, TRIM(REPLACE(reference_code, \'`\', \'\')) AS uc_po_number, marketplace AS uc_channel_name, invoice_code AS uc_invoice_code, Warehouse_Name AS uc_facility, shippingPackageStatus AS uc_shippingPackageStatus, order_status AS uc_order_status, SUM(subordeR_quantity) AS uc_sold_qty, SUM(selling_price) AS uc_selling_price FROM `asaya-data-room-487110.Maplemonk.unicommerce_b2b_sales_report_fact_items` WHERE order_status IN (\'COMPLETE\', \'PROCESSING\') AND invoiceDate IS NOT NULL GROUP BY 1, 2, 3, 4, 5, 6, 7, 8, 9) select * from po_grn as pg left join uc on pg.po_number = uc.uc_po_number)), zone as (SELECT distinct Destination,Zone FROM `asaya-data-room-487110.Maplemonk.Gs_warehouse_zone_mapping_swiggy` ) select a.*, coalesce(a.po_release_date_1, c.order_Date) as po_release_Date, \"swiggy\" as platform, safe_divide(c.quantity, count(1) over (partition by coalesce(a.po_release_date_1, c.order_Date) order by 1)) sales_quantity, safe_divide(c.selling_price, count(1) over (partition by coalesce(a.po_release_date_1, c.order_Date) order by 1)) selling_price, zone from po_uc_grn a left join zone as z on a.po_warehouse_location =z.Destination full outer join ( select ordeR_Date, sum(quantity) quantity, sum(selling_price) selling_price, from asaya-data-room-487110.Maplemonk.asaya_sales_dashboard WHERE cleaned_channel = \'SWIGGYINSTAMART\' AND secondary_order_type = 1 group by 1 ) c on a.po_release_date_1 = c.order_Date ; create or replace table asaya-data-room-487110.maplemonk.nykaa_po_fill_date_pre as SELECT a.*, coalesce(a.po_release_date_1, b.order_Date) as po_release_Date, b.order_date, case when lower(appointment_status) = \'no show\' then row_number () over (partition by appt_po_number order by appt_created_datetime) + 1 when lower(appointment_status) not in (\'rejected\',\'cancelled\') then row_number () over (partition by appt_po_number order by appt_created_datetime) end as rw1, safe_divide(b.quantity, count(1) over (partition by coalesce(a.po_release_date_1, b.order_Date) order by 1)) sales_quantity, safe_divide(b.selling_price, count(1) over (partition by coalesce(a.po_release_date_1, b.order_Date) order by 1)) selling_price, c.zone, \"Nykaa\" as Platform FROM ( (WITH latest_po_snapshot AS ( SELECT po_number, MAX(scraped_at) AS max_scraped_at FROM `asaya-data-room-487110.Maplemonk.nykaa_po_report` GROUP BY po_number ), po_data AS ( SELECT p.po_number, p.vendor_name AS po_vendor_name, p.warehouse_location AS po_warehouse_location, p.seller_name AS po_seller_name, p.po_created_by, p.po_status, SAFE_CAST(p.po_qty AS FLOAT64) AS po_qty, SAFE_CAST(p.po_amount AS FLOAT64) AS po_amount, COALESCE( SAFE.PARSE_DATE(\'%d-%m-%Y\', p.issue_date), SAFE.PARSE_DATE(\'%Y-%m-%d\', p.issue_date) ) AS po_release_date_1 FROM `asaya-data-room-487110.Maplemonk.nykaa_po_report` p JOIN latest_po_snapshot l ON p.po_number = l.po_number AND p.scraped_at = l.max_scraped_at WHERE p.po_number != \'nan\' ), latest_grn_snapshot AS ( SELECT po_number, MAX(scraped_at) AS max_scraped_at FROM `asaya-data-room-487110.Maplemonk.nykaa_grn_report` GROUP BY po_number ), base_grn AS ( SELECT COALESCE( SAFE.PARSE_DATE(\'%d-%m-%Y\', g.grn_date), SAFE.PARSE_DATE(\'%Y-%m-%d\', g.grn_date) ) AS grn_date, g.warehouse_location AS grn_warehouse, g.vendor_name AS grn_vendor_name, g.grn_status, g.grn_number, g.po_number, SUM(SAFE_CAST(g.grn_qty AS FLOAT64)) AS grn_qty, SUM(SAFE_CAST(g.grn_amount AS FLOAT64)) AS grn_amount FROM `asaya-data-room-487110.Maplemonk.nykaa_grn_report` g JOIN latest_grn_snapshot l ON g.po_number = l.po_number AND g.scraped_at = l.max_scraped_at GROUP BY 1, 2, 3, 4, 5, 6 ), po_totals AS ( SELECT po_number, SUM(grn_qty) AS total_grn_qty, SUM(grn_amount) AS total_grn_amount FROM base_grn GROUP BY po_number ), primary_grn AS ( SELECT grn_date, grn_warehouse, grn_vendor_name, grn_status, grn_number, po_number, grn_qty, grn_amount, ROW_NUMBER() OVER ( PARTITION BY po_number ORDER BY grn_qty DESC ) AS rn FROM base_grn ), grn_final AS ( SELECT p.grn_date, p.grn_warehouse, p.grn_vendor_name, p.grn_status, p.grn_number, p.po_number AS grn_po_number, t.total_grn_qty AS grn_qty, t.total_grn_amount AS grn_amount FROM primary_grn p JOIN po_totals t ON p.po_number = t.po_number WHERE p.rn = 1 ), uc_data AS ( SELECT DATE(Order_Date) AS uc_order_date, DATE(invoiceDate) AS uc_invoice_date, DATE(Dispatch_Date) AS uc_dispatch_date, reference_code AS uc_po_number, marketplace AS uc_channel_name, invoice_code AS uc_invoice_code, Warehouse_Name AS uc_facility, shippingPackageStatus AS uc_shippingPackageStatus, order_status AS uc_order_status, SUM(subordeR_quantity) AS uc_sold_qty, SUM(selling_price) AS uc_selling_price FROM `asaya-data-room-487110.Maplemonk.unicommerce_b2b_sales_report_fact_items` WHERE order_status In (\'COMPLETE\', \"PROCESSING\") AND invoiceDate IS NOT NULL GROUP BY 1, 2, 3, 4, 5, 6, 7, 8, 9 ), uc_final AS ( SELECT uc_order_date, uc_invoice_date, uc_dispatch_date, uc_po_number, uc_channel_name, uc_invoice_code, uc_facility, uc_shippingPackageStatus, uc_order_status, uc_sold_qty, uc_selling_price, ROW_NUMBER() OVER ( PARTITION BY uc_po_number ORDER BY uc_order_date DESC, uc_invoice_date DESC ) AS rn FROM uc_data ), latest_appt_snap AS ( SELECT appointment_id, po, MAX(scraped_at) AS max_scraped_at FROM `asaya-data-room-487110.Maplemonk.nykaa_appointment_po_report` GROUP BY appointment_id, po ), appt_base AS ( SELECT a.po AS appt_po_number, COALESCE( SAFE.PARSE_DATE(\'%d-%m-%Y\', a.appointment_date), SAFE.PARSE_DATE(\'%Y-%m-%d\', a.appointment_date) ) AS appointment_date, COALESCE( SAFE.PARSE_DATETIME(\'%d-%m-%Y, %I:%M %p\', a.created_on), DATETIME(SAFE.PARSE_DATE(\'%d-%m-%Y\', a.created_on)), DATETIME(SAFE.PARSE_DATE(\'%Y-%m-%d\', a.created_on)) ) AS appt_created_datetime, a.appointment_id, a.appointment_status, ROW_NUMBER() OVER ( PARTITION BY a.po ORDER BY COALESCE( SAFE.PARSE_DATE(\'%d-%m-%Y\', a.appointment_date), SAFE.PARSE_DATE(\'%Y-%m-%d\', a.appointment_date) ) DESC, CASE a.appointment_status WHEN \'Received\' THEN 1 WHEN \'Partially Received\' THEN 2 WHEN \'Unloaded\' THEN 3 WHEN \'Booking Confirmed\' THEN 4 WHEN \'No Show\' THEN 5 WHEN \'Rejected\' THEN 6 WHEN \'Cancelled\' THEN 7 ELSE 8 END ASC, a.appointment_id DESC ) AS appt_rn FROM `asaya-data-room-487110.Maplemonk.nykaa_appointment_po_report` a JOIN latest_appt_snap l ON a.appointment_id = l.appointment_id AND a.po = l.po AND a.scraped_at = l.max_scraped_at ) SELECT po.po_number, po.po_vendor_name, po.po_warehouse_location, po.po_seller_name, po.po_created_by, po.po_status, po.po_release_date_1, appt.appointment_id, appt.appointment_date, appt.appt_po_number, appt.appointment_status, appt.appt_created_datetime, CASE WHEN appt.appt_po_number IS NOT NULL AND appt.appt_rn != 1 THEN 0 ELSE po