Cancelled\') THEN appointment_date END) OVER (PARTITION BY appt_po_number ORDER BY appointment_date ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) AS last_non_no_show_before FROM asaya-data-room-487110.maplemonk.nykaa_po_fill_date_pre ) SELECT *, CASE WHEN appointment_status IN (\'Rejected\', \'Cancelled\') THEN NULL WHEN appointment_status = \'No Show\' AND next_status IS NULL THEN rn + 1 WHEN appointment_status = \'No Show\' AND next_status NOT IN (\'No Show\', \'Rejected\', \'Cancelled\') AND next_status IS NOT NULL AND last_non_no_show_before IS NOT NULL THEN rn + 1 WHEN appointment_status = \'No Show\' THEN NULL ELSE rn END AS rw FROM data ORDER BY appointment_date ; create or replace table asaya-data-room-487110.maplemonk.nykaa_po_fill_date as select po_number, po_vendor_name, po_warehouse_location, po_seller_name, po_created_by, po_status, po_release_date_1, appointment_id, appointment_date, appt_po_number, appointment_status, appt_created_datetime, po_qty, po_amount, grn_date, grn_po_number, grn_warehouse, grn_vendor_name, grn_status, grn_number, grn_qty, grn_amount, uc_order_date, uc_invoice_date, uc_dispatch_date, uc_po_number, uc_channel_name, uc_invoice_code, uc_facility, uc_shippingPackageStatus, uc_order_status, uc_sold_qty, uc_selling_price, po_release_Date, order_date, rw1, sales_quantity, selling_price, zone, Platform, rn, next_status, last_non_no_show_before, rw from asaya-data-room-487110.maplemonk.nykaa_po_fill_date_intermediate union all select po_number, po_vendor_name, po_warehouse_location, null po_seller_name, null po_created_by, po_status, po_release_date, null appointment_id, appointment_date, null appt_po_number, null appointment_status, null appt_created_datetime, po_qty, po_amount, cast(grn_date as date) grn_Date, null grn_po_number, null grn_warehouse, null grn_vendor_name, null grn_status, null grn_number, grn_qty, grn_amount, uc_order_date, uc_invoice_date, uc_dispatch_date, uc_po_number, uc_channel_name, uc_invoice_code, uc_facil